import{_ as e,o,c as a,a3 as r}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse(`{"title":"Design","description":"Customize a form's colors, logo, background image, and field style.","frontmatter":{"title":"Design","description":"Customize a form's colors, logo, background image, and field style."},"headers":[],"relativePath":"en/formulare/gestaltung.md","filePath":"en/formulare/gestaltung.md","lastUpdated":1788108473000}`),i={name:"en/formulare/gestaltung.md"};function n(s,t,l,d,h,c){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to &quot;Design&quot;">​</a></h1><p>In the <strong>Layout</strong> tab of the form editor, you adjust the appearance. The settings are grouped into four sections.</p><h2 id="text" tabindex="-1">Text <a class="header-anchor" href="#text" aria-label="Permalink to &quot;Text&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Form title</strong></td><td>Heading, placeholder <em>Add title…</em></td></tr><tr><td><strong>Description</strong></td><td>Intro text, placeholder <em>Add description…</em></td></tr><tr><td><strong>Submit button text</strong></td><td>Label on the submit button</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">The button text can be specific</p><p><em>Submit</em> is neutral but says nothing. <em>Send application</em>, <em>Request appointment</em>, or <em>Report issue</em> tells people what happens next — and raises the completion rate.</p></div><h2 id="images-and-logo" tabindex="-1">Images and logo <a class="header-anchor" href="#images-and-logo" aria-label="Permalink to &quot;Images and logo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Background image</strong></td><td>Image in the header area of the form</td></tr><tr><td><strong>Logo</strong></td><td>Your own logo above the form</td></tr><tr><td><strong>Width</strong></td><td>Logo width as a percentage of the form width</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">The logo is plan-dependent</p><p>Your own logo is only available on the top plan. Background image and colors are available on every plan.</p></div><div class="tip custom-block"><p class="custom-block-title">Choose logo width conservatively</p><p>The value is a percentage of the form width, not a pixel size. Values around 20 to 30 percent usually look better on mobile devices than large logos that take up half the screen there.</p></div><h2 id="colors" tabindex="-1">Colors <a class="header-anchor" href="#colors" aria-label="Permalink to &quot;Colors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Applies to</th></tr></thead><tbody><tr><td><strong>Primary color</strong></td><td>Accents throughout the form</td></tr><tr><td><strong>Button color</strong></td><td>Submit button</td></tr><tr><td><strong>Background color</strong></td><td>Area behind the form</td></tr><tr><td><strong>Card background color</strong></td><td>The form&#39;s own surface</td></tr><tr><td><strong>Header color</strong></td><td>Header area</td></tr><tr><td><strong>Card without shadow</strong></td><td>Removes the drop shadow</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Two colors are usually enough</p><p>Primary color and button color are enough for a coherent result. Set all six settings to different values and the form quickly starts to look busy.</p><p>Pay attention to <strong>contrast</strong>: light text on a light background is unreadable on mobile in sunlight.</p></div><h2 id="field-style" tabindex="-1">Field style <a class="header-anchor" href="#field-style" aria-label="Permalink to &quot;Field style&quot;">​</a></h2><p>Two options:</p><table tabindex="0"><thead><tr><th>Option</th><th>Appearance</th></tr></thead><tbody><tr><td><strong>No border</strong></td><td>The label floats up as you type</td></tr><tr><td><strong>With border</strong></td><td>The label stays fixed above the bordered field</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">&quot;With border&quot; is usually the safer choice</p><p>With <em>No border</em>, the label sits inside the field at first — some people mistake it for an already-entered value. On longer forms with many fields, <em>With border</em> is clearer.</p></div><h2 id="hiding-the-product-notice" tabindex="-1">Hiding the product notice <a class="header-anchor" href="#hiding-the-product-notice" aria-label="Permalink to &quot;Hiding the product notice&quot;">​</a></h2><p>Forms carry a default notice, <em>Create your own free form with …</em>. <strong>Hide product notice</strong> removes it.</p><p>Plan-dependent.</p><h2 id="checking-the-appearance" tabindex="-1">Checking the appearance <a class="header-anchor" href="#checking-the-appearance" aria-label="Permalink to &quot;Checking the appearance&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">View at both widths</p><p><strong>Preview in new tab</strong> shows the form as people filling it out will see it. Shrink the window to smartphone width — that&#39;s where oversized logos, poor contrast, and overly long labels first stand out.</p><p>When embedding, there&#39;s also a <em>Smartphone preview</em> and <em>Computer preview</em>. → <a href="/en/formulare/formular-teilen">Sharing a form</a></p></div><h2 id="limits-of-the-design-options" tabindex="-1">Limits of the design options <a class="header-anchor" href="#limits-of-the-design-options" aria-label="Permalink to &quot;Limits of the design options&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">What isn&#39;t possible in a form</p><ul><li><strong>No custom CSS</strong>, no free positioning</li><li><strong>No conditional display</strong> of fields</li><li><strong>No multi-column layout</strong> — fields stack vertically</li></ul><p>If you need that, a <a href="/en/seiten/was-sind-seiten">Page</a> is the right tool: it offers layout blocks, HTML, and <a href="/en/seiten/sichtbarkeit">conditional visibility</a>.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/formulare/felder-konfigurieren">Configuring fields</a></li><li><a href="/en/formulare/erfolgsseite">Success page and redirect</a></li><li><a href="/en/formulare/formular-teilen">Sharing a form</a></li></ul>',25)])])}const p=e(i,[["render",n]]);export{u as __pageData,p as default};
